CREATE TABLE IF NOT EXISTS "reviews" (
	"id" serial PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"rating" integer DEFAULT 5 NOT NULL,
	"date" date NOT NULL,
	"text_es" text NOT NULL,
	"text_en" text NOT NULL,
	"visible" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
-- Las reseñas que hasta ahora vivían en los textos de la web. Sólo si la tabla está vacía:
-- si la migración se repite, no duplica ni pisa lo que ella haya editado.
INSERT INTO "reviews" ("name", "rating", "date", "text_es", "text_en")
SELECT * FROM (VALUES
  ('Ana', 5, '2026-01-01'::date, 'La mejor experiencia en la que participamos en Buenos Aires (mejor que los agradables espectáculos de tango turístico, o agradables excursiones de estancia y clases de cocina). Las historias sobre cómo y por qué apareció y floreció el tango fueron puestas en perspectiva por la verdadera milonga de hoy, viendo cómo los lugareños viven y respiran el tango hoy, con sus rituales y su increíble atmósfera. Soy una persona tímida e introvertida que nunca fue a una clase de baile, y estoy ansioso por comenzar a aprender tango cuando regrese a casa. Muy recomendable.', 'Best experience we participated in Buenos Aires (better than the nice tourist tango shows, or nice estancia tours and cooking classes). The stories about how and why tango appeared and flourished were put in perspective by the real today''s milonga - seeing how the locals live and breathe the tango today, with it''s rituals and amazing atmosphere. I am a shy introverted person who never went to a dance class, and I can''t wait to start learning tango when I go home. Highly recommend.'),
  ('Murray', 5, '2025-12-01'::date, 'Incluso si estás remotamente interesado en el baile, esto es algo que debes hacer. El conocimiento y la pasión de María brillan haciendo de esta la mejor experiencia que hemos tenido en las ciudades que hemos viajado hasta ahora. Muy auténtico, ya que aquí es donde están los locales, haciendo lo suyo en una tarde de día laboral, y así explicado por nuestra hermosa anfitriona.', 'Even if you are remotely interested in dance, this is a must do. Maria’s knowledge and passion shines through making it the best experience we have had in the cities we have traveled so far. Very authentic, as this is where the locals are, doing their thing on a weekday afternoon, and so explained by our beautiful host.'),
  ('Amanda', 5, '2025-12-01'::date, 'Marie es increíblemente conocedora de la historia y el origen del Tango de Buenos Aires y lo explicó de una manera cautivadora, humorística e interactiva. Tuvimos varias paradas donde aprendimos no solo sobre la historia del Tango sino también algunos movimientos básicos de tango - todo intercalado con información sobre el Distrito de Teatros y los bocadillos y pasteles argentinos favoritos y típicos. Terminamos en una Milonga (donde los locales van a bailar Tango) donde fuimos invitados a bailar y hacer nuevos amigos de Buenos Aires que pacientemente nos enseñaron algunos movimientos nuevos! ¡Experiencia increíble y totalmente recomendada. No necesitas tener experiencia en baile para disfrutarlo. Gracias Marie!', 'Marie is incredibly knowledgeable about the history and origin of Buenos Aires Tango and explained this in a captivating, humorous and interactive way. We had several stops where we learnt not only about Tango history but also a few basic tango moves - all interspersed with information about the Theatre District and favourite & typical Argentinian snacks & cakes. We finished off at a Malinga (where locals go to Tango) where we were invited to dance and make some new Buenos Aires friends who patiently taught us some new moves! Unbelievable experience and thoroughly recommend. You do not need to have any dance experience to enjoy. Thank you Marie!'),
  ('Luca', 5, '2025-11-01'::date, 'María es una excelente guía de tango. No solo tiene mucho conocimiento sobre la historia del tango, ella misma es una bailarina de tango experta y apasionada.', 'Maria is an excellent tango guide. Not only she is very knowledgeable about the history of tango, she is an expert and passionate tango dancer herself.'),
  ('Xiaolei', 5, '2025-08-01'::date, 'Debido al clima, fui la única persona que participó en la experiencia hoy, así que se convirtió en un grupo privado. María es muy meticulosa sobre los orígenes históricos y el auge y caída del tango, y me dio mucha información, lo cual fue revelador. También disfruté mucho de los pasos de tango y el método que me enseñó en la calle. Finalmente, fuimos a bailar. Lo sorprendente es que, como principiante, recibí dos invitaciones, lo que hizo que mi experiencia general fuera muy completa. Gracias. Altamente recomendado.', 'Due to the weather, I was the only person who participated in the experience today, so it became a private group. Maria is very meticulous about the historical origins and the rise and fall of tango, and she gave me a lot of information, which was eye-opening. I also really enjoyed the tango steps and the method she taught me on the street. Finally, we went dancing. The amazing thing is that, as a beginner, I received two invitations, which made my overall experience very complete. Thank you. Highly recommended.'),
  ('Cynthia', 5, '2026-02-01'::date, 'Una experiencia verdaderamente maravillosa, me encantó cada momento. Maria es genial y muy bien informado sobre todo lo relacionado con el tango. Bailar en la milonga fue lo más destacado de mi estadía en Buenos Aires. Recomiendo encarecidamente este recorrido a cualquiera que visite BA, ya que es una experiencia verdaderamente única.', 'A truly wonderful experience, I loved every moment of it. Maria is great and very knowledgeable about everything Tango. Dancing at the Milonga was the highlight of my time in Buenos Aires. I highly recommend this tour to anyone visiting BA as it is a truly unique experience.'),
  ('Shahid', 5, '2026-02-01'::date, '¡El recorrido a pie fue genial! Maria es una anfitriona muy bien informada y le apasiona mucho el tango y explicó todo muy bien, incluida la historia, las costumbres e incluso cómo bailar', 'the walking tour was great! Maria is a very knowledgeable host and is very passionate about tango and explained everything very well including the history, customs and even how to dance'),
  ('Oliver', 5, '2026-05-01'::date, 'María brindó una introducción perfecta al tango, sus antecedentes e historia, su desarrollo a lo largo del tiempo y su presente. Además, hubo esta introducción a una milonga en Buenos Aires con todos los detalles y complejidades que nunca podrías descubrir sin una guía tan especial. ¡Sin duda voy a repetir este recorrido con María la próxima vez que esté en Buenos Aires!', 'Maria provided a perfect introduction into Tango, its background and history, its development over time and its present. On top, there was this introduction to a Milonga in Buenos Aires with all the details and intricacies which you would never be available to discover without such a special  guide. I will repeat this tour with Maria next time I am in Buenos Aires, definitely!'),
  ('Heidi bech Geschwendtner', 5, '2026-01-01'::date, 'Tuve un día increíble con María en un tour privado y aprendí mucho sobre el rico y fascinante mundo del tango. Su conocimiento es profundo y lo comparte de una manera tan natural y atractiva. Nos divertimos mucho, reímos mucho y realmente disfrutamos cada momento. María no solo es increíblemente conocedora sino también una persona maravillosa para ser guiada. Gracias por una experiencia fantástica — recomiendo mucho a María.', 'I had an amazing day with Maria on a private tour and learned so much about the rich and fascinating world of tango. Her knowledge is deep and shared in such a natural, engaging way. We had a lot of fun, laughed a lot, and truly enjoyed every moment. Maria is not only incredibly knowledgeable but also a wonderful person to be guided by. Thank you for a fantastic experience — I highly recommend Maria.'),
  ('Thomas Obel', 5, '2025-12-01'::date, 'Realmente disfruté nuestro día privado con María. Ella es muy conocedora, fácil de hablar, e hizo que la historia del tango cobrara vida con grandes historias. Una experiencia divertida, relajada y excelente. Mis más cálidas recomendaciones. Saludos cordiales, Thomas', 'I really enjoyed our private day with Maria. She is very knowledgeable, easy to talk to, and made tango history come alive with great stories. A fun, relaxed, and excellent experience. My warmest recommendations. Best Regards Thomas'),
  ('Flor Arbiser', 5, '2025-04-01'::date, 'Me uní al Tour de Tango de María Inés solo para acompañar a turistas. Pero resultó ser increíblemente entretenido para mí, una nativa de Buenos Aires y apenas entusiasta del tango. María Inés conoce la historia del tango tan profundamente que te hace sentir como si fueras parte de sus orígenes, como si estuvieras en un bar en La Boca a principios del siglo pasado. Habla un inglés perfecto, casi musical. Para colmo, enseña algunos pasos con facilidad y encanto, y te lleva dentro de milongas auténticas. Allí, María Inés se pone sus tacos y demuestra ser una de las mejores bailarinas.', 'I joined María Inés''s Tango Tour just to accompany tourists. But it turned out to be incredibly entertaining for me, a Buenos Aires native and hardly any tango enthusiast. María Inés knows the history of tango so deeply that she makes you feel like you''re part of its origins, as if you were in a bar in La Boca at the beginning of the last century. She speaks perfect, almost musical English. To top it all off, she teaches a few steps with ease and charm, and takes you inside authentic milongas. There, María Inés puts on her heels and proves herself to be one of the best dancers.'),
  ('Lisa Bryzek', 5, '2025-03-01'::date, '¡María fue una guía maravillosa! Traje a mi suegra y a mi hijo a Buenos Aires para bailar tango ya que mi hijo ha estado tomando clases de tango. Quería una experiencia más local pero estaba intimidada de entrar a una milonga por nuestra cuenta. Encontré a María en experiencias de Airbnb y fue muy fácil comunicarse con ella. Primero aprendimos sobre la historia del tango y luego nos llevó a una milonga y nos enseñó la etiqueta de la milonga. María llevó a mi hijo a la pista de baile para "romper el hielo" y desde ese momento mi hijo fue invitado a bailar toda la noche tanto por hombres como por mujeres y ¡se divirtió mucho! Gracias María por esta maravillosa experiencia local! ¡Recomiendo mucho!', 'María was a wonderful guide! I brought my mother in law and son to Buenos Aires to dance tango since my son has been taking tango lessons. I wanted a more local experience but was intimidated to go into a milonga by ourselves. I found Maria on Airbnb experiences and she was very easy to communicate with. We first learned about the history of tango and then She brought us to a milonga and taught us the milonga etiquette. Maria took my son out on the dance floor to “break the ice” and from that moment on my son was asked to dance all night long by both men and women and had a blast! Thank you Maria for this wonderful local experience! I highly recommend!!'),
  ('Tulip Order Office', 5, '2025-03-01'::date, 'El diciembre pasado mi familia tuvo una velada tan maravillosa con María Inés. Aprendimos todo sobre la historia del tango, luego visitamos un salón de tango para ver algunos bailes increíbles. Fue uno de los momentos más memorables para mí. Gracias y cariños de Bill, John, Milo, Teo y Otto', 'Last December my family had such a wonderful evening with Maria Ines. We learnt all about the history of the tango, then visited a tango hall to watch some amazing dancing. It was one of the most memorable times for me. Thank you and love from Bill, John, Milo, Teo and Otto')
) AS v ("name", "rating", "date", "text_es", "text_en")
WHERE NOT EXISTS (SELECT 1 FROM "reviews");
